package com.personal.assistant.module.export.controller;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.personal.assistant.common.security.SecurityContextHelper;import com.personal.assistant.module.devlog.entity.DevLog;import com.personal.assistant.module.devlog.mapper.DevLogMapper;import com.personal.assistant.module.learning.entity.LearningRecord;import com.personal.assistant.module.learning.mapper.LearningRecordMapper;import jakarta.servlet.http.HttpServletResponse;import org.springframework.web.bind.annotation.*;import java.io.*;import java.nio.charset.*;import java.util.*;@RestController @RequestMapping("/api/export")public class DataExportController{private final DevLogMapper devlogs;private final LearningRecordMapper records;public DataExportController(DevLogMapper devlogs,LearningRecordMapper records){this.devlogs=devlogs;this.records=records;}@GetMapping(value="/devlogs",produces="text/markdown")public void devlogs(HttpServletResponse response)throws IOException{response.setCharacterEncoding(StandardCharsets.UTF_8.name());response.setHeader("Content-Disposition","attachment; filename=devlogs.md");Long uid=SecurityContextHelper.currentUserId();for(DevLog row:devlogs.selectList(new LambdaQueryWrapper<DevLog>().eq(DevLog::getUserId,uid).orderByDesc(DevLog::getOccurredAt)))response.getWriter().write(row.getMarkdownContent()+"\n\n---\n\n");}@GetMapping(value="/learning-records",produces="text/csv")public void learning(HttpServletResponse response)throws IOException{response.setCharacterEncoding(StandardCharsets.UTF_8.name());response.setHeader("Content-Disposition","attachment; filename=learning-records.csv");response.getWriter().write("\uFEFF时间,时长,内容,结果,问题,下一步\n");Long uid=SecurityContextHelper.currentUserId();for(LearningRecord row:records.selectList(new LambdaQueryWrapper<LearningRecord>().eq(LearningRecord::getUserId,uid).orderByDesc(LearningRecord::getRecordTime)))response.getWriter().printf("%s,%s,\"%s\",\"%s\",\"%s\",\"%s\"%n",row.getRecordTime(),row.getDurationMinutes(),e(row.getContent()),e(row.getResult()),e(row.getProblem()),e(row.getNextAction()));}private String e(String value){return value==null?"":value.replace("\"","\"\"");}}
